// === Tab: mySketch ===
let shaderProg;

const vert = `
  precision mediump float;
  attribute vec3 aPosition;
  varying vec2 vTexCoord;

  void main() {
    vTexCoord = (aPosition.xy + 1.0) * 0.5;
    gl_Position = vec4(aPosition, 1.0);
  }
`;

const frag = `
  precision mediump float;
  uniform float u_time;
  varying vec2 vTexCoord;

	float sec(float x) {
    return 1.0 / cos(x);
  }

	float csc(float x) {
    return 1.0 / sin(x);
  }

  float cot(float x) {
    return 1.0 / tan(x);
  }

  void main() {
    vec2 uv = vTexCoord - 0.5;
    float zoom = cot(u_time * 0.5) * 0.5 + 1.0;
    uv *= zoom * 2.0;

    float r = length(uv);
    float a = atan(uv.y, uv.x);
    float wave = csc(a * 6.0 + u_time * 2.0) * 0.5 + 0.5;
    float radialPattern = sec(r * 10.0 - u_time * 3.0) * 0.5 + 0.5;
    float scanlines = sin(uv.y * 40.0) * 0.1;

    // Noise distortion
    float distortion = cot(uv.x * 5.0 + u_time) * 0.05;
    uv.y += distortion;

    // Chromatic Aberration Effect
    float ca_offset = 0.005 * cos(u_time);
    vec3 chromatic = vec3(
      sin(r * 10.0 - u_time * 3.0 + ca_offset),
      sin(r * 10.0 - u_time * 3.0),
      sin(r * 10.0 - u_time * 3.0 - ca_offset)
    ) * 0.5 + 0.5;

    // Color Cycling
    vec3 neonColor = vec3(0.5 + 0.5 * cos(u_time + vec3(0.0, 2.0, 4.0)));
    vec3 finalColor = mix(neonColor, chromatic, wave * radialPattern) + scanlines;

    // Glitch Effect (horizontal shift)
    float glitch = step(0.99, fract(sin(uv.y * 100.0 + u_time * 5.0) * 43758.5453123));
    uv.x += glitch * 0.02;

    // Glow Effect
    vec3 glow = vec3(1.0, 0.5, 0.8) * smoothstep(0.3, 0.1, r);
    finalColor += glow * 0.3;

    // Pixelation Effect
    float pixelSize = 0.01 + 0.005 * cot(u_time * 2.0);
    uv = floor(uv / pixelSize) * pixelSize;

    // Circular Ripple Effect
    float ripple = sin(r * 15.0 - u_time * 5.0) * 0.2;
    uv.x += ripple * 0.1;
    uv.y += ripple * 0.1;

    // Grid Overlay Effect
    float grid = mod(uv.x * 20.0, 1.0) > 0.9 || mod(uv.y * 20.0, 1.0) > 0.9 ? 0.3 : 0.0;
    finalColor += vec3(grid);

    // Flickering Effect
    float flicker = sin(u_time * 10.0) * 0.05;
    finalColor *= 1.0 + flicker;

    // Wavy Displacement
    uv.x += sin(uv.y * 10.0 + u_time * 3.0) * 0.02;
    uv.y += cos(uv.x * 10.0 + u_time * 3.0) * 0.02;

    // Radial Blur Effect
    finalColor = mix(finalColor, vec3(0.0), smoothstep(0.7, 1.2, r));

    // Starfield Effect
    float starfield = step(0.995, fract(sin(dot(uv, vec2(12.9898, 78.233)) * 43758.5453 + u_time)));
    finalColor -= vec3(starfield * 0.8);

    // Plasma Effect
    float plasma = cos(uv.x * 10.0 + u_time) * sin(uv.y * 10.0 + u_time) * 0.5 + 0.5;
    finalColor = mix(finalColor, vec3(1.0, 0.2, 0.3), plasma * 0.3);

    // Motion Blur Effect
    float motionBlur = smoothstep(0.0, 1.0, abs(csc(u_time * 0.5)));
    finalColor = mix(finalColor, vec3(0.0), motionBlur * 0.2);

    // Heat Wave Effect
    uv.x += sin(u_time + uv.y * 20.0) * 0.01;
    uv.y += cos(u_time + uv.x * 20.0) * 0.01;

    // Static Noise Overlay
    float staticNoise = fract(sin(dot(uv, vec2(12.9898, 78.233)) * 43758.5453));
    finalColor += vec3(staticNoise * 0.1);

    // Water Ripple Effect
    float waterRipple = tan(r * 12.0 - u_time * 6.0) * 0.05;
    uv.x += waterRipple;
    uv.y += waterRipple;

    // Electric Pulse Effect
    float electricPulse = tan(u_time * 8.0 + uv.x * 15.0) * 0.3;
    finalColor -= vec3(electricPulse, electricPulse * 0.5, electricPulse * 0.2);

    // Vignette
    float vignette = smoothstep(1.2, 0.5, r);
    gl_FragColor = vec4(finalColor * vignette, 1.0);
  }
`;

function setup() {
  createCanvas(windowWidth, windowWidth*.75, WEBGL);
  noStroke();
  shaderProg = createShader(vert, frag);
}

function draw() {
  shader(shaderProg);
  shaderProg.setUniform('u_time', millis() / 1000.0);

  beginShape();
  vertex(-1, -1, 0);
  vertex(1, -1, 0);
  vertex(1, 1, 0);
  vertex(-1, 1, 0);
  endShape(CLOSE);
}

function windowResized() {
  resizeCanvas(width, height);
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

